#!/bin/bash
set -e

# WhatsApp advance payment confirmation:
# - Auto-sends ONLY for advance payments (collectAdvance), not regular
#   invoice payments -- deferred via after() so collection speed is
#   unaffected, same fix as applied to invoice payments earlier.
# - Manual 'Send WhatsApp' button added to Receipt for ANY payment
#   (advance or regular), synchronous with sent/warning/error feedback.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/actions.js"
echo "Wrote app/(main)/payments/actions.js"

mkdir -p "app/(main)/payments/receipt"
echo "" | base64 -d > "app/(main)/payments/receipt/receipt-tab.js"
echo "Wrote app/(main)/payments/receipt/receipt-tab.js"

git add "lib/whatsapp.js" "app/(main)/payments/actions.js" "app/(main)/payments/receipt/receipt-tab.js"
git commit -m "Add WhatsApp advance payment confirmation: auto-send (advance only, deferred) + manual Receipt button"
git push

echo "Done."
